(6704279, 1002822, 132251, '<td valign="top">I love the softness of this. Almost looks like <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=91783" rel="nofollow" target="_blank">ScooterMcNutty</a> in the shot</td>', 'I love the softness of this. Almost looks like  ScooterMcNutty in the shot', '2012-03-08 11:09:44.000000', NULL, 1),
