INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6709037, 1002713, 7711, '<td valign="top">the subject sure is "leaping" but the image is too small to adequately evaluate, and what can be seen, shows the subject completely out of focus. Not every part of him would need to be in focus, but some part, even just the head, would be better.</td>', 'the subject sure is "leaping" but the image is too small to adequately evaluate, and what can be seen, shows the subject completely out of focus. Not every part of him would need to be in focus, but some part, even just the head, would be better.', '2012-03-13 18:46:27.000000', NULL, 1),
(6709038, 1002862, 7711, '<td valign="top">good lighting at the top of the photo, but the bottom suffers from shadows cast by the trees and bench. This had the effect of drawing the eye up and away from the main subject.</td>', 'good lighting at the top of the photo, but the bottom suffers from shadows cast by the trees and bench. This had the effect of drawing the eye up and away from the main subject.', '2012-03-13 18:47:31.000000', NULL, 1),
(6709040, 1001678, 7711, '<td valign="top">fun photo! I would have preferred a wider and less tall shot (more like a panorama ratio) so the subjects could be better composed. Also, the sky being blown out in places takes away from the subjects themselves.</td>', 'fun photo! I would have preferred a wider and less tall shot (more like a panorama ratio) so the subjects could be better composed. Also, the sky being blown out in places takes away from the subjects themselves.', '2012-03-13 18:48:36.000000', NULL, 1),
(6709041, 1002782, 7711, '<td valign="top">great use of focus and blur to give the sense of action!</td>', 'great use of focus and blur to give the sense of action!', '2012-03-13 18:49:08.000000', NULL, 1),
(6709042, 1002866, 7711, '<td valign="top">poor crop (top of mouse is cropped out a bit, not balanced spacing all around) and the mouse''s face is blown out.</td>', 'poor crop (top of mouse is cropped out a bit, not balanced spacing all around) and the mouse''s face is blown out.', '2012-03-13 18:49:56.000000', NULL, 1),
(6709044, 1002798, 7711, '<td valign="top">I don''t know why, but this photo really appeals to me. I love the look on her face and the saturated but not overly bright colours of the taxis. Well done. :)</td>', 'I don''t know why, but this photo really appeals to me. I love the look on her face and the saturated but not overly bright colours of the taxis. Well done. :)', '2012-03-13 18:51:01.000000', NULL, 1),
(6709046, 1002836, 7711, '<td valign="top">conceptually awesome, compositionally, it suffers from excessive softness.</td>', 'conceptually awesome, compositionally, it suffers from excessive softness.', '2012-03-13 18:52:31.000000', NULL, 1),
(6709047, 1001702, 7711, '<td valign="top">if only this awesome subject was against a better background, you could have moved yourself back and really gotten a great image!</td>', 'if only this awesome subject was against a better background, you could have moved yourself back and really gotten a great image!', '2012-03-13 18:53:39.000000', NULL, 1),
(6709048, 1002830, 7711, '<td valign="top">good lighting and nice colours.</td>', 'good lighting and nice colours.', '2012-03-13 18:54:20.000000', NULL, 1),
(6709051, 1002648, 28359, '<td valign="top">Great team work on the timing. Nice job!</td>', 'Great team work on the timing. Nice job!', '2012-03-13 18:55:56.000000', NULL, 1),
(6709053, 1002711, 7711, '<td valign="top">Seems like you might be new (if I''m wrong, sorry!). You should submit larger images so they can be better evaluated. As for what we can see here, its out of focus, and too tight a crop to really get a feel for the subject. Also needs better lighting as the sky is too bright and the subject appears then too dark.</td>', 'Seems like you might be new (if I''m wrong, sorry!). You should submit larger images so they can be better evaluated. As for what we can see here, its out of focus, and too tight a crop to really get a feel for the subject. Also needs better lighting as the sky is too bright and the subject appears then too dark.', '2012-03-13 18:56:37.000000', NULL, 1),
(6709054, 1002648, 7711, '<td valign="top">a bit too much USM, but great subject and composition and nice colours.</td>', 'a bit too much USM, but great subject and composition and nice colours.', '2012-03-13 18:57:55.000000', NULL, 1),
